// R0 >= 0, R1 >= 0, and R0*R1 < 32768.

// R2 = 0; i = 0
// LOOP: if i == R1 goto END
//       R2 = R2 + R0; i = i + 1; goto LOOP
// END: goto END

    @R2
    M=0
    @i
    M=0
(LOOP)
    @i
    D=M
    @R1
    D=D-M
    @END
    D;JEQ
    @R0
    D=M
    @R2
    M=D+M
    @i
    M=M+1
    @LOOP
    0;JMP
(END)
    @END
    0;JMP

