CHIP CPU {
    IN inM[16], instruction[16], reset;
    OUT outM[16], writeM, addressM[15], pc[15];
    PARTS:
    // decode
    // instruction[15]: 0 = A-instruction, 1 = C-instruction
    Not(in=instruction[15], out=isA);
    // A register load: A-instruction or (C-instruction and d1)
    And(a=instruction[15], b=instruction[5], out=loadAbyC);
    Or(a=isA, b=loadAbyC, out=loadA);
    Mux16(a=instruction, b=aluOut, sel=instruction[15], out=aIn);
    ARegister(in=aIn, load=loadA, out=aOut, out[0..14]=addressM);
    // ALU second input: A or M
    Mux16(a=aOut, b=inM, sel=instruction[12], out=amOut);
    // D register
    And(a=instruction[15], b=instruction[4], out=loadD);
    DRegister(in=aluOut, load=loadD, out=dOut);
    // ALU
    ALU(x=dOut, y=amOut,
        zx=instruction[11], nx=instruction[10],
        zy=instruction[9], ny=instruction[8],
        f=instruction[7], no=instruction[6],
        out=aluOut, out=outM, zr=zr, ng=ng);
    // writeM
    And(a=instruction[15], b=instruction[3], out=writeM);
    // jump logic
    // positive = !zr && !ng
    Or(a=zr, b=ng, out=notPos);
    Not(in=notPos, out=pos);
    And(a=instruction[0], b=pos, out=jgt);
    And(a=instruction[1], b=zr, out=jeq);
    And(a=instruction[2], b=ng, out=jlt);
    Or(a=jgt, b=jeq, out=jgteq);
    Or(a=jgteq, b=jlt, out=jump);
    And(a=jump, b=instruction[15], out=pcLoad);
    PC(in=aOut, load=pcLoad, inc=true, reset=reset, out[0..14]=pc);
}
```

Note: jump bits: instruction[0]=JGT, [1]=JEQ, [2]=JLT. Dest bits: [3]=M(d3), [4]=D(d2), [5]=A(d1). Correct.

PC out is 16 bits; out[0..14]=pc, bit15 unconnected — fine.

