    PARTS:
    // Instruction decode
    // instruction[15]==0: A-instruction (@value)
    // instruction[15]==1: C-instruction (dest=comp;jump)
    // C-instruction fields: a=inst[12], c=inst[6..11],
    //   d1(A)=inst[5], d2(D)=inst[4], d3(M)=inst[3],
    //   j1(JLT)=inst[2], j2(JEQ)=inst[1], j3(JGT)=inst[0]
    Not(in=instruction[15], out=isAInst);

    // A register: holds the instruction value for an A-instruction,
    // or the ALU output when d1==1 in a C-instruction
    And(a=instruction[15], b=instruction[5], out=loadAbyC);
    Or(a=isAInst, b=loadAbyC, out=loadA);
    Mux16(a=instruction, b=aluOut, sel=instruction[15], out=aIn);
    ARegister(in=aIn, load=loadA, out=aOut, out[0..14]=addressM);

    // D register: loaded from the ALU output when d2==1
    And(a=instruction[15], b=instruction[4], out=loadD);
    DRegister(in=aluOut, load=loadD, out=dOut);

    // ALU operands: x=D, y=A or M (a-bit selects)
    Mux16(a=aOut, b=inM, sel=instruction[12], out=amOut);
    ALU(x=dOut, y=amOut,
        zx=instruction[11], nx=instruction[10],
        zy=instruction[9], ny=instruction[8],
        f=instruction[7], no=instruction[6],
        out=aluOut, out=outM, zr=zr, ng=ng);

    // writeM: C-instruction with d3==1
    And(a=instruction[15], b=instruction[3], out=writeM);

    // Jump logic: compute jump condition from zr/ng and j1,j2,j3
    Or(a=zr, b=ng, out=notPos);
    Not(in=notPos, out=pos);
    And(a=instruction[2], b=ng, out=jlt);
    And(a=instruction[1], b=zr, out=jeq);
    And(a=instruction[0], b=pos, out=jgt);
    Or(a=jlt, b=jeq, out=jle);
    Or(a=jle, b=jgt, out=jumpCond);
    And(a=jumpCond, b=instruction[15], out=pcLoad);

    // Program counter: load on jump, else increment
    PC(in=aOut, load=pcLoad, inc=true, reset=reset, out[0..14]=pc);
}

