"""A minimal nand2tetris HDL simulator (combinational + clocked, tick/tock semantics)."""
import os
import re


def strip_comments(text):
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.S)
    text = re.sub(r'//[^\n]*', '', text)
    return text


SIDE_RE = re.compile(r'^\s*(\w+)\s*(?:\[\s*(\d+)\s*(?:\.\.\s*(\d+)\s*)?\])?\s*$')


def parse_side(s):
    m = SIDE_RE.match(s)
    if not m:
        raise ValueError('bad pin/wire spec: %r' % s)
    name = m.group(1)
    if m.group(2) is None:
        return (name, None, None)
    lo = int(m.group(2))
    hi = int(m.group(3)) if m.group(3) is not None else lo
    return (name, lo, hi)


class ChipDef:
    def __init__(self, name, ins, outs, raw_parts):
        self.name = name
        self.ins = ins      # name -> width
        self.outs = outs    # name -> width
        self.raw_parts = raw_parts  # (chipname, [((pin,plo,phi),(wire,wlo,whi))])


DECL_RE = re.compile(r'^(\w+)\s*(?:\[\s*(\d+)\s*\])?$')


def parse_chip(text):
    text = strip_comments(text)
    m = re.search(r'CHIP\s+(\w+)\s*\{', text)
    name = m.group(1)
    body = text[m.end():]
    body = body[:body.rindex('}')]
    pi = body.index('PARTS:')
    decl, pstr = body[:pi], body[pi + 6:]
    ins, outs = {}, {}
    dmap = {'IN': ins, 'OUT': outs}
    cur = None
    for tok in re.split(r'\b(IN|OUT)\b', decl):
        tok = tok.strip()
        if tok in dmap:
            cur = dmap[tok]
            continue
        if cur is None or not tok:
            continue
        for item in tok.split(';'):
            for piece in item.split(','):
                piece = piece.strip()
                if not piece:
                    continue
                dm = DECL_RE.match(piece)
                cur[dm.group(1)] = int(dm.group(2)) if dm.group(2) else 1
    raw_parts = []
    for stmt in pstr.split(';'):
        stmt = ' '.join(stmt.split())
        if not stmt:
            continue
        pm = re.match(r'^(\w+)\s*\((.*)\)$', stmt)
        cname, cstr = pm.group(1), pm.group(2)
        conns = []
        for c in cstr.split(','):
            if not c.strip():
                continue
            lhs, rhs = c.split('=')
            conns.append((parse_side(lhs), parse_side(rhs)))
        raw_parts.append((cname, conns))
    return ChipDef(name, ins, outs, raw_parts)


# ---------------- built-in chips ----------------

class Builtin:
    pin_dirs = {}
    clocked = False
    volatile = False  # output may change without input change

    def pins(self):
        return self.pin_dirs

    def eval_comb(self, inputs):
        raise NotImplementedError

    def capture(self, inputs):
        pass

    def commit(self):
        pass


class NandB(Builtin):
    pin_dirs = {'a': ('in', 1), 'b': ('in', 1), 'out': ('out', 1)}

    def eval_comb(self, inputs):
        return {'out': 1 - (inputs.get('a', 0) & inputs.get('b', 0))}


class DFFB(Builtin):
    pin_dirs = {'in': ('in', 1), 'out': ('out', 1)}
    clocked = True

    def __init__(self):
        self.state = 0
        self.pending = 0

    def eval_comb(self, inputs):
        return {'out': self.state}

    def capture(self, inputs):
        self.pending = inputs.get('in', 0) & 1

    def commit(self):
        self.state = self.pending


class _RegB(Builtin):
    pin_dirs = {'in': ('in', 16), 'load': ('in', 1), 'out': ('out', 16)}
    clocked = True

    def __init__(self):
        self.state = 0
        self.pending = 0

    def eval_comb(self, inputs):
        return {'out': self.state}

    def capture(self, inputs):
        self.pending = (inputs.get('in', 0) & 0xFFFF) if inputs.get('load', 0) else self.state

    def commit(self):
        self.state = self.pending


class ARegisterB(_RegB):
    pass


class DRegisterB(_RegB):
    pass


class ROM32KB(Builtin):
    pin_dirs = {'address': ('in', 15), 'out': ('out', 16)}
    volatile = True

    def __init__(self):
        self.mem = [0] * 32768

    def load_program(self, words):
        self.mem[:len(words)] = words

    def eval_comb(self, inputs):
        return {'out': self.mem[inputs.get('address', 0) & 0x7FFF]}


class ScreenB(Builtin):
    pin_dirs = {'in': ('in', 16), 'load': ('in', 1),
                'address': ('in', 13), 'out': ('out', 16)}
    clocked = True

    def __init__(self):
        self.mem = [0] * 8192
        self.pending = []

    def eval_comb(self, inputs):
        return {'out': self.mem[inputs.get('address', 0) & 0x1FFF]}

    def capture(self, inputs):
        if inputs.get('load', 0):
            self.pending.append((inputs.get('address', 0) & 0x1FFF,
                                 inputs.get('in', 0) & 0xFFFF))

    def commit(self):
        for a, v in self.pending:
            self.mem[a] = v
        self.pending = []


class KeyboardB(Builtin):
    pin_dirs = {'out': ('out', 16)}
    volatile = True

    def __init__(self):
        self.key = 0

    def eval_comb(self, inputs):
        return {'out': self.key & 0xFFFF}


class RAM16KB(Builtin):
    pin_dirs = {'in': ('in', 16), 'load': ('in', 1),
                'address': ('in', 14), 'out': ('out', 16)}
    clocked = True

    def __init__(self):
        self.mem = [0] * 16384
        self.pending = []

    def eval_comb(self, inputs):
        return {'out': self.mem[inputs.get('address', 0) & 0x3FFF]}

    def capture(self, inputs):
        if inputs.get('load', 0):
            self.pending.append((inputs.get('address', 0) & 0x3FFF,
                                 inputs.get('in', 0) & 0xFFFF))

    def commit(self):
        for a, v in self.pending:
            self.mem[a] = v
        self.pending = []


BUILTINS = {'Nand': NandB, 'DFF': DFFB, 'ARegister': ARegisterB,
            'DRegister': DRegisterB, 'ROM32K': ROM32KB, 'Screen': ScreenB,
            'Keyboard': KeyboardB, 'RAM16K': RAM16KB}


# ---------------- HDL chip instances ----------------

class ChipInstance:
    def __init__(self, sim, cdef):
        self.sim = sim
        self.cdef = cdef
        self.pins_in = {n: 0 for n in cdef.ins}
        self.parts = []
        self.part_meta = []   # {'in': [(pin,plo,phi,src)], 'comb': bool}
        self.drivers = {}     # wire -> [(pidx, pin, plo, phi, wlo, whi)]
        self.wcache = {}
        self.pcache = {}
        self.gcache = {}      # pidx -> (key, outputs), combinational only
        self.has_seq = False
        for cname, conns in cdef.raw_parts:
            sub = sim.make(cname)
            pidx = len(self.parts)
            self.parts.append(sub)
            subpins = sub.pins()
            meta = {'in': [], 'comb': not (sub.has_seq if isinstance(sub, ChipInstance)
                                           else (sub.clocked or sub.volatile))}
            for (pin, plo, phi), (wn, wlo, whi) in conns:
                kind, pw = subpins[pin]
                plo2, phi2 = (0, pw - 1) if plo is None else (plo, phi)
                pwidth = phi2 - plo2 + 1
                wlo2, whi2 = (0, pwidth - 1) if wlo is None else (wlo, whi)
                if whi2 - wlo2 + 1 != pwidth:
                    raise ValueError('%s: width mismatch on pin %s' % (cdef.name, pin))
                if kind == 'in':
                    if wn in ('true', 'false'):
                        src = ('const', 1 if wn == 'true' else 0)
                    else:
                        src = ('wire', wn, wlo2, whi2)
                    meta['in'].append((pin, plo2, phi2, src))
                else:
                    self.drivers.setdefault(wn, []).append(
                        (pidx, pin, plo2, phi2, wlo2, whi2))
            self.part_meta.append(meta)
            sub_seq = sub.has_seq if isinstance(sub, ChipInstance) else sub.clocked
            if sub_seq:
                self.has_seq = True

    def pins(self):
        d = {n: ('in', w) for n, w in self.cdef.ins.items()}
        d.update({n: ('out', w) for n, w in self.cdef.outs.items()})
        return d

    def get_wire(self, w):
        v = self.wcache.get(w)
        if v is not None:
            return v
        if w in self.cdef.ins:
            v = self.pins_in.get(w, 0)
        else:
            v = 0
            for (pidx, pin, plo, phi, wlo, whi) in self.drivers.get(w, ()):
                pv = self.part_out(pidx, pin)
                v |= ((pv >> plo) & ((1 << (phi - plo + 1)) - 1)) << wlo
        self.wcache[w] = v
        return v

    def part_out(self, pidx, pin):
        return self.eval_part(pidx).get(pin, 0)

    def collect_inputs(self, pidx):
        inputs = {}
        for (pin, plo, phi, src) in self.part_meta[pidx]['in']:
            if src[0] == 'const':
                bits = src[1]
            else:
                bits = (self.get_wire(src[1]) >> src[2]) & ((1 << (src[3] - src[2] + 1)) - 1)
            inputs[pin] = inputs.get(pin, 0) | (bits << plo)
        return inputs

    def eval_part(self, pidx):
        outs = self.pcache.get(pidx)
        if outs is not None:
            return outs
        sub = self.parts[pidx]
        inputs = self.collect_inputs(pidx)
        if self.part_meta[pidx]['comb']:
            key = tuple(sorted(inputs.items()))
            g = self.gcache.get(pidx)
            if g is not None and g[0] == key:
                outs = g[1]
            else:
                outs = sub.eval_comb(inputs)
                self.gcache[pidx] = (key, outs)
        else:
            outs = sub.eval_comb(inputs)
        self.pcache[pidx] = outs
        return outs

    def eval_comb(self, inputs):
        # used when this instance is a part of another chip
        for n in self.cdef.ins:
            self.pins_in[n] = inputs.get(n, 0)
        self.wcache = {}
        self.pcache = {}
        return {o: self.get_wire(o) for o in self.cdef.outs}

    def eval(self, inputs):
        # top-level: merge inputs, keep previous values for unspecified pins
        self.pins_in.update(inputs)
        self.wcache = {}
        self.pcache = {}
        return {o: self.get_wire(o) for o in self.cdef.outs}

    def tick(self):
        for pidx, sub in enumerate(self.parts):
            if isinstance(sub, ChipInstance):
                if sub.has_seq:
                    sub.tick()
            elif sub.clocked:
                sub.capture(self.collect_inputs(pidx))

    def tock(self):
        for sub in self.parts:
            if isinstance(sub, ChipInstance):
                if sub.has_seq:
                    sub.tock()
            elif sub.clocked:
                sub.commit()

    def find_builtins(self, cls, acc=None):
        if acc is None:
            acc = []
        for sub in self.parts:
            if isinstance(sub, ChipInstance):
                sub.find_builtins(cls, acc)
            elif isinstance(sub, cls):
                acc.append(sub)
        return acc


class Simulator:
    def __init__(self, dirs, overrides=()):
        self.defs = {}
        self.overrides = set(overrides)
        for d in dirs:
            for f in sorted(os.listdir(d)):
                if f.endswith('.hdl'):
                    cdef = parse_chip(open(os.path.join(d, f)).read())
                    self.defs[cdef.name] = cdef

    def make(self, name):
        if name in self.overrides or name not in self.defs:
            if name not in BUILTINS:
                raise KeyError('unknown chip: ' + name)
            return BUILTINS[name]()
        return ChipInstance(self, self.defs[name])

"""Hack assembler and CPU emulator for testing .asm programs."""

COMP = {
    '0': (0, 0b101010), '1': (0, 0b111111), '-1': (0, 0b111010),
    'D': (0, 0b001100), 'A': (0, 0b110000), 'M': (1, 0b110000),
    '!D': (0, 0b001101), '!A': (0, 0b110001), '!M': (1, 0b110001),
    '-D': (0, 0b001111), '-A': (0, 0b110011), '-M': (1, 0b110011),
    'D+1': (0, 0b011111), 'A+1': (0, 0b110111), 'M+1': (1, 0b110111),
    'D-1': (0, 0b001110), 'A-1': (0, 0b110010), 'M-1': (1, 0b110010),
    'D+A': (0, 0b000010), 'D+M': (1, 0b000010),
    'D-A': (0, 0b010011), 'D-M': (1, 0b010011),
    'A-D': (0, 0b000111), 'M-D': (1, 0b000111),
    'D&A': (0, 0b000000), 'D&M': (1, 0b000000),
    'D|A': (0, 0b010101), 'D|M': (1, 0b010101),
}
JUMP = {'': 0, 'JGT': 1, 'JEQ': 2, 'JGE': 3, 'JLT': 4, 'JNE': 5, 'JLE': 6, 'JMP': 7}

PREDEFINED = {'SP': 0, 'LCL': 1, 'ARG': 2, 'THIS': 3, 'THAT': 4,
              'SCREEN': 16384, 'KBD': 24576}
for i in range(16):
    PREDEFINED['R%d' % i] = i


def assemble(text):
    lines = []
    for raw in text.split('\n'):
        line = raw.split('//')[0].strip()
        if line:
            lines.append(line)
    # pass 1: labels
    symbols = dict(PREDEFINED)
    rom = 0
    prog = []
    for line in lines:
        if line.startswith('('):
            symbols[line[1:-1]] = rom
        else:
            prog.append(line)
            rom += 1
    # pass 2
    words = []
    next_var = 16
    for line in prog:
        if line.startswith('@'):
            sym = line[1:]
            if sym.isdigit():
                val = int(sym)
            else:
                if sym not in symbols:
                    symbols[sym] = next_var
                    next_var += 1
                val = symbols[sym]
            assert 0 <= val <= 0x7FFF, line
            words.append(val)
        else:
            if ';' in line:
                lhs, jump = line.split(';')
            else:
                lhs, jump = line, ''
            if '=' in lhs:
                dest, comp = lhs.split('=')
            else:
                dest, comp = '', lhs
            dest = dest.strip()
            comp = comp.strip()
            a, cbits = COMP[comp]
            dbits = 0
            for ch in set(dest):
                dbits |= {'M': 1, 'D': 2, 'A': 4}[ch]
            words.append(0b111 << 13 | a << 12 | cbits << 6 | dbits << 3 | JUMP[jump])
    return words


def alu16(x, y, c):
    zx, nx, zy, ny, f, no = [(c >> s) & 1 for s in (5, 4, 3, 2, 1, 0)]
    if zx:
        x = 0
    if nx:
        x = x ^ 0xFFFF
    if zy:
        y = 0
    if ny:
        y = y ^ 0xFFFF
    r = (x + y) & 0xFFFF if f else (x & y)
    if no:
        r = r ^ 0xFFFF
    return r


def run(prog, ram, steps, keyboard=0):
    """Emulate the Hack CPU. ram is a list of >=24577 words. Returns (A, D, PC)."""
    A = D = PC = 0
    for _ in range(steps):
        instr = prog[PC] if PC < len(prog) else 0
        if instr >> 15 == 0:
            A = instr
            PC += 1
            continue
        a = (instr >> 12) & 1
        c = (instr >> 6) & 0x3F
        d = (instr >> 3) & 7
        j = instr & 7
        y = ram[A] if a else A
        if a and A == 24576:
            y = keyboard
        r = alu16(D, y & 0xFFFF, c)
        jlt, jeq, jgt = (j >> 2) & 1, (j >> 1) & 1, j & 1
        ng, zr = (r >> 15) & 1, 1 if r == 0 else 0
        pos = 1 - (ng | zr)
        if d & 4:
            A = r
        if d & 2:
            D = r
        if d & 1:
            ram[A] = r
        PC = A if (jlt & ng) | (jeq & zr) | (jgt & pos) else PC + 1
    return A, D, PC

